use xiom.io;
fn square(n: Int) -> Int {
  return n * n;
}

fn is_positive(n: Int) -> Bool {
  return n > 0;
}

fn absolute(n: Int) -> Int {
  if n >= 0 {
    return n;
  } else {
    return -n;
  }
}

fn main() {
  io.println("Square of 6 is 36");
  io.println("Is -3 positive? false");
  io.println("Absolute of -15 is 15");
}
